// Step 1 of verifying the Convex -> n8n signature (HMAC-SHA256 over
// "<timestamp>.<body>"). n8n lowercases incoming header names.

for (const name of ["CONVEX_TO_N8N_SECRET","CONVEX_SITE_URL"]) {
  if (!$env[name]) throw new Error(`n8n env var ${name} is not set (see n8n/.env.example)`);
}

const { headers = {}, body = {} } = $input.first().json;
const timestamp = String(headers['x-lendloop-timestamp'] ?? '');

// Convex sends compact JSON.stringify output. Parsing and re-serializing
// keeps key order and formatting, so this rebuilds the signed bytes exactly.
const rawBody = JSON.stringify(body);

return [{
  json: {
    timestamp,
    providedSignature: String(headers['x-lendloop-signature'] ?? ''),
    toSign: `${timestamp}.${rawBody}`,
    payload: body,
  },
}];

// Step 2: reject stale timestamps (replay protection) and compare signatures
// in constant time. Nothing below this node runs for an unverified request.
const MAX_SKEW_SECONDS = 300;
const { timestamp, providedSignature, expectedSignature, payload } = $input.first().json;

function constantTimeEqual(a, b) {
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
}

let reason = null;
if (!timestamp || !providedSignature) reason = 'missing_headers';
else if (!/^\d+$/.test(timestamp) || Math.abs(Date.now() / 1000 - Number(timestamp)) > MAX_SKEW_SECONDS) reason = 'stale_timestamp';
else if (!constantTimeEqual(providedSignature, `sha256=${expectedSignature}`)) reason = 'bad_signature';

if (reason) console.warn(`[LendLoop] Rejected loan-event webhook: ${reason}`);
return [{ json: { valid: reason === null, reason, payload } }];

// Turns the minimal payload into a human message. The payload only has
// what's needed: event, recipient name/email, tool name and dates.
const p = $input.first().json.payload;
const range = p.startDate === p.endDate ? p.startDate : `${p.startDate} to ${p.endDate}`;

const templates = {
  loan_requested: {
    label: 'Request',
    subject: `New request for your ${p.toolName}`,
    text: `Hi ${p.recipient.name}, a neighbor wants to borrow your ${p.toolName} (${range}). Open LendLoop to approve or decline.`,
  },
  loan_approved: {
    label: 'Approval',
    subject: `Approved: ${p.toolName}`,
    text: `Hi ${p.recipient.name}, your request for the ${p.toolName} (${range}) was approved.`,
  },
  loan_declined: {
    label: 'Decline',
    subject: `Declined: ${p.toolName}`,
    text: `Hi ${p.recipient.name}, your request for the ${p.toolName} (${range}) was declined.`,
  },
  loan_returned: {
    label: 'Return',
    subject: `Returned: ${p.toolName}`,
    text: `Hi ${p.recipient.name}, the ${p.toolName} was marked as returned. Thanks for using LendLoop!`,
  },
};

const t = templates[p.event];
if (!t) throw new Error(`Unknown loan event: ${p.event}`);

return [{
  json: {
    eventId: p.eventId,
    label: t.label,
    to: p.recipient.email,
    toName: p.recipient.name,
    subject: t.subject,
    text: t.text,
  },
}];

// MOCK DELIVERY: logs instead of emailing. To send real email, replace this
// node with an email node (e.g. Send Email or Resend over HTTP) and pass
// eventId as the provider's idempotency key, so a retried webhook doesn't
// send twice.

// Logs never contain a full email address.
function maskEmail(email) {
  const [user, domain] = String(email).split('@');
  return domain ? `${user.slice(0, 1)}***@${domain}` : '***';
}

const n = $input.first().json;
console.log(`[LendLoop mock notification] to=${maskEmail(n.to)} subject="${n.subject}" text="${n.text}"`);
return [{ json: { ...n, deliveredAt: new Date().toISOString() } }];

// Builds the exact string that the next (Crypto) node signs. The body is
// serialized once here and sent as a raw string, so the bytes signed are
// the bytes Convex verifies.
function signable(payload) {
  const body = JSON.stringify(payload);
  const timestamp = String(Math.floor(Date.now() / 1000));
  return { body, timestamp, toSign: `${timestamp}.${body}` };
}

const n = $input.first().json;
// Only the event id and a display message go back: no email address.
return [{
  json: signable({
    eventId: n.eventId,
    message: `${n.label} notification sent to ${n.toName} (mock)`,
  }),
}];
